-- Domain 24: Community, Reviews & UGC | functions
-- Generated by tools/split_by_domain.py. Statements keep their original order tag (@seq).

-- @seq 615
CREATE FUNCTION public.ugc_current_customer_id() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT pca.customer_id FROM public.portal_customer_accounts pca
  WHERE pca.auth_user_id = auth.uid() AND pca.status = 'active' LIMIT 1
$$;

-- @seq 616
CREATE FUNCTION public.ugc_current_tenant_id() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT pca.tenant_id FROM public.portal_customer_accounts pca
  WHERE pca.auth_user_id = auth.uid() AND pca.status = 'active' LIMIT 1
$$;

-- @seq 617
CREATE FUNCTION public.ugc_refresh_product_counters(p_tenant uuid, p_product uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  INSERT INTO public.ugc_product_counters
    (product_id, tenant_id, like_count, favorite_count, comment_count,
     review_count, rating_sum, post_count, updated_at)
  SELECT
    p_product, p_tenant,
    (SELECT count(*) FROM public.ugc_reactions r
       WHERE r.tenant_id = p_tenant AND r.target_type = 'product' AND r.target_id = p_product),
    (SELECT count(*) FROM public.customer_wishlist_items w
       WHERE w.tenant_id = p_tenant AND w.product_id = p_product::text),
    (SELECT count(*) FROM public.ugc_comments c
       WHERE c.tenant_id = p_tenant AND c.product_id = p_product AND c.status = 'published'),
    (SELECT count(*) FROM public.reviews v
       WHERE v.tenant_id = p_tenant AND v.product_id = p_product AND v.status = 'published'),
    (SELECT COALESCE(sum(v.rating), 0) FROM public.reviews v
       WHERE v.tenant_id = p_tenant AND v.product_id = p_product AND v.status = 'published'),
    (SELECT count(*) FROM public.ugc_posts q
       WHERE q.tenant_id = p_tenant AND q.product_id = p_product AND q.status = 'published'),
    now()
  ON CONFLICT (product_id) DO UPDATE SET
    tenant_id      = EXCLUDED.tenant_id,
    like_count     = EXCLUDED.like_count,
    favorite_count = EXCLUDED.favorite_count,
    comment_count  = EXCLUDED.comment_count,
    review_count   = EXCLUDED.review_count,
    rating_sum     = EXCLUDED.rating_sum,
    post_count     = EXCLUDED.post_count,
    updated_at     = now();
END $$;

-- @seq 618
CREATE FUNCTION public.ugc_trg_refresh_counters() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  rows  jsonb[] := '{}';
  r     jsonb;
  v_prod text;
BEGIN
  BEGIN  -- a counter problem must never block the real write
    IF TG_OP IN ('INSERT','UPDATE') THEN rows := array_append(rows, to_jsonb(NEW)); END IF;
    IF TG_OP IN ('UPDATE','DELETE') THEN rows := array_append(rows, to_jsonb(OLD)); END IF;
    FOREACH r IN ARRAY rows LOOP
      IF TG_TABLE_NAME = 'ugc_reactions' THEN
        v_prod := CASE WHEN r->>'target_type' = 'product' THEN r->>'target_id' END;
      ELSE
        v_prod := r->>'product_id';
      END IF;
      IF v_prod IS NOT NULL AND v_prod ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        PERFORM public.ugc_refresh_product_counters((r->>'tenant_id')::uuid, v_prod::uuid);
      END IF;
    END LOOP;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'ugc counter refresh failed on %: %', TG_TABLE_NAME, SQLERRM;
  END;
  RETURN NULL;
END $_$;

